//! The Polish model, generated by flexion-train from configs/src/polish.rs: one
//! module per part of speech (and per helper model), each a
//! [`flexion::PosModel`]. Don't edit by hand.

use flexion::{Model, PosModel, Spelling, SpellingStrings};

mod noun;
mod adjective;
mod verb;
mod pronoun;
mod numeral;

static STRINGS: SpellingStrings<'static> = SpellingStrings {
    stress_marks: "",
    stress_table: "",
    vowels: "aeiouyąęó",
    implicit: "",
    fold_from: "",
    fold_to: "",
    strip_marks: "",
    unmark_from: "",
    unmark_to: "",
    syllabic: "",
    mute: "",
    diphthongs: "",
    hiatus: "",
};

/// The model, in the config's order of parts of speech (helper models
/// after).
pub(crate) fn build() -> Model<'static> {
    Model::new(
        Spelling::new(true, false, STRINGS),
        vec![
            &noun::Noun as &dyn PosModel,
            &adjective::Adjective as &dyn PosModel,
            &verb::Verb as &dyn PosModel,
            &pronoun::Pronoun as &dyn PosModel,
            &numeral::Numeral as &dyn PosModel,
        ],
    )
}
